## Cache Repeated Function Calls

Use a module-level Map to cache function results when the same function is called repeatedly with the same inputs during render.

**Incorrect (redundant computation):**

```typescript
function ProjectList({ projects }: { projects: Project[] }) {
  return (
    <div>
      {projects.map(project => {
        // slugify() called 100+ times for same project names
        const slug = slugify(project.name)

        return <ProjectCard key={project.id} slug={slug} />
      })}
    </div>
  )
}
```

**Correct (cached results):**

```typescript
// Module-level cache
const slugifyCache = new Map<string, string>()

function cachedSlugify(text: string): string {
  if (slugifyCache.has(text)) {
    return slugifyCache.get(text)!
  }
  const result = slugify(text)
  slugifyCache.set(text, result)
  return result
}

function ProjectList({ projects }: { projects: Project[] }) {
  return (
    <div>
      {projects.map(project => {
        // Computed only once per unique project name
        const slug = cachedSlugify(project.name)

        return <ProjectCard key={project.id} slug={slug} />
      })}
    </div>
  )
}
```

**Simpler pattern for single-value functions:**

```typescript
let isLoggedInCache: boolean | null = null

function isLoggedIn(): boolean {
  if (isLoggedInCache !== null) {
    return isLoggedInCache
  }

  isLoggedInCache = document.cookie.includes('auth=')
  return isLoggedInCache
}

// Clear cache when auth changes
function onAuthChange() {
  isLoggedInCache = null
}
```

Use a Map (not a hook) so it works everywhere: utilities, event handlers, not just React components.

Reference: [How we made the Vercel Dashboard twice as fast](https://vercel.com/blog/how-we-made-the-vercel-dashboard-twice-as-fast)

import { type NextRequest, NextResponse } from 'next/server';
import { createOAuthValues, setOAuthCookies } from '@/lib/server/auth';

export async function GET(request: NextRequest) {
  const clientId = process.env.NEXT_PUBLIC_VERCEL_APP_CLIENT_ID;
  if (!clientId) {
    return Response.json(
      { error: { code: 'auth_not_configured', message: 'Sign in with Vercel is not configured' } },
      { status: 503 },
    );
  }
  const values = createOAuthValues();
  await setOAuthCookies(values);
  const parameters = new URLSearchParams({
    client_id: clientId,
    redirect_uri: `${request.nextUrl.origin}/api/auth/callback`,
    state: values.state,
    nonce: values.nonce,
    code_challenge: values.challenge,
    code_challenge_method: 'S256',
    response_type: 'code',
    scope: 'openid email profile',
  });
  return NextResponse.redirect(`https://vercel.com/oauth/authorize?${parameters}`);
}

import { type NextRequest, NextResponse } from 'next/server';
import { consumeOAuthCookies, issueSession, verifyVercelIdToken } from '@/lib/server/auth';
import { getStore } from '@/lib/server/get-store';

type TokenResponse = { id_token?: string };

export async function GET(request: NextRequest) {
  try {
    const code = request.nextUrl.searchParams.get('code');
    if (!code) throw new Error('Authorization code is missing');
    const oauth = await consumeOAuthCookies(request, request.nextUrl.searchParams.get('state'));
    const clientId = process.env.NEXT_PUBLIC_VERCEL_APP_CLIENT_ID;
    const clientSecret = process.env.VERCEL_APP_CLIENT_SECRET;
    if (!clientId || !clientSecret) throw new Error('Sign in with Vercel is not configured');
    const response = await fetch('https://api.vercel.com/login/oauth/token', {
      method: 'POST',
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({
        grant_type: 'authorization_code',
        client_id: clientId,
        client_secret: clientSecret,
        code,
        code_verifier: oauth.verifier,
        redirect_uri: `${request.nextUrl.origin}/api/auth/callback`,
      }),
      cache: 'no-store',
    });
    if (!response.ok) throw new Error('Vercel rejected the authorization code');
    const token = (await response.json()) as TokenResponse;
    if (!token.id_token) throw new Error('Vercel did not return an ID token');
    const identity = await verifyVercelIdToken(token.id_token, oauth.nonce);
    await getStore().ensureUser(identity);
    await issueSession(identity);
    return NextResponse.redirect(new URL('/', request.url));
  } catch (error) {
    console.error(error);
    return NextResponse.redirect(new URL('/?authError=1', request.url));
  }
}

import { AuthError, issueSession } from '@/lib/server/auth';
import { getStore } from '@/lib/server/get-store';
import { handleRouteError } from '@/lib/server/http';
import { isLocalAuthEnabled, isLocalAuthRequest, localIdentity } from '@/lib/server/local-auth';

export async function POST(request: Request) {
  try {
    if (!isLocalAuthEnabled()) return new Response(null, { status: 404 });
    if (!isLocalAuthRequest(request)) {
      throw new AuthError('forbidden', 'Local sign-in requires a same-origin loopback request');
    }
    const identity = localIdentity();
    await getStore().ensureUser(identity);
    await issueSession(identity);
    const requestUrl = new URL(request.url);
    const redirectOrigin =
      request.headers.get('origin') ??
      `${requestUrl.protocol}//${request.headers.get('host') ?? requestUrl.host}`;
    return Response.redirect(new URL('/', redirectOrigin), 303);
  } catch (error) {
    return handleRouteError(error);
  }
}

import { clearSession, requireSession, verifyMutationRequest } from '@/lib/server/auth';
import { handleRouteError } from '@/lib/server/http';

export async function POST(request: Request) {
  try {
    const session = await requireSession();
    verifyMutationRequest(request, session);
    await clearSession();
    return Response.json({ ok: true });
  } catch (error) {
    return handleRouteError(error);
  }
}

import { getSession } from '@/lib/server/auth';

export async function GET() {
  const session = await getSession();
  if (!session) {
    return Response.json({ session: null }, { status: 401 });
  }
  return Response.json({ session });
}

import { AuthError, issueSession } from '@/lib/server/auth';
import { getStore } from '@/lib/server/get-store';
import {
  hostedAuthOrigin,
  hostedIdentity,
  isHostedAuthEnabled,
  isHostedAuthRequest,
  verifyHostedAccessCode,
} from '@/lib/server/hosted-auth';
import { handleRouteError } from '@/lib/server/http';

export async function POST(request: Request) {
  try {
    if (!isHostedAuthEnabled()) return new Response(null, { status: 404 });
    if (!isHostedAuthRequest(request)) {
      throw new AuthError('forbidden', 'Hosted sign-in requires a same-origin request');
    }
    const formData = await request.formData();
    const accessCode = formData.get('accessCode');
    if (!verifyHostedAccessCode(typeof accessCode === 'string' ? accessCode : null)) {
      return Response.redirect(new URL('/?accessError=1', hostedAuthOrigin(request)), 303);
    }
    const identity = hostedIdentity();
    await getStore().ensureUser(identity);
    await issueSession(identity);
    return Response.redirect(new URL('/', hostedAuthOrigin(request)), 303);
  } catch (error) {
    return handleRouteError(error);
  }
}

